<?php
/**
 * ZP Suite v2.2.187 — header opacity CMS control + dark contact active cards.
 * - Adds final CSS emitted at footer so inline template/Elementor styles cannot override it.
 * - Header sticky whiteness is controlled in ZAPROJEKTOWANI Suite → Header → Sticky header — biel / przezroczystość 1–100.
 */
if (!defined('ABSPATH')) { exit; }

function zp_suite_187_header_white_strength(){
  $raw = function_exists('zp_suite_opt') ? zp_suite_opt('header.sticky_white_strength', '96') : '96';
  $val = is_numeric($raw) ? (float) $raw : 96;
  $val = max(1, min(100, $val));
  return $val / 100;
}

add_action('wp_head', function(){
  if (is_admin()) { return; }
  $a = zp_suite_187_header_white_strength();
  $a1 = max(0, min(1, $a));
  $aTop = max(0, min(1, $a1 + .025));
  $aBot = max(0, min(1, $a1 - .035));
  ?>
  <style id="zp-suite-2-2-187-head-vars">
    :root{
      --zp-header-sticky-white-a:<?php echo esc_html(number_format($a1, 3, '.', '')); ?>;
      --zp-header-sticky-white-top:<?php echo esc_html(number_format($aTop, 3, '.', '')); ?>;
      --zp-header-sticky-white-bottom:<?php echo esc_html(number_format($aBot, 3, '.', '')); ?>;
      --zp-contact-dark-card:linear-gradient(135deg,#020407 0%,#05070b 35%,#071426 72%,#102a4f 100%);
    }
  </style>
  <?php
}, 999999);

